ax.axhline(0,color='#333333',linewidth=.8);ax.set_xticks(x,[name(r) for r in S]);ax.set_ylabel('Mean saving vs fixed reference (ms)');ax.legend(frameon=False);ax.spines[['top','right']].set_visible(False);fig.tight_layout()
